'use strict';

// MODULES //

var isInteger = require( '@stdlib/math/base/assert/is-integer' );
var floor = require( '@stdlib/math/base/special/floor' );
var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );
var typeOf = require( '@stdlib/utils/type-of' );
var Uint32Array = require( '@stdlib/array/uint32' );
var Float64Array = require( '@stdlib/array/float64' );


// VARIABLES //

var hash;


// FUNCTIONS //

/**
* Copies a sequence of elements within a typed array to another location in the same array.
* Optimized implementation that copies in chunks based on the element size when possible.
*
* @private
* @param {TypedArray} arr - input typed array
* @param {integer} target - target index
* @param {integer} [start=0] - source start index
* @param {integer} [end=arr.length] - source end index
* @param {integer} bytesPerElement - number of bytes per element
* @returns {TypedArray} modified input array
*/
function copyWithinTypedArray( arr, target, start, end, bytesPerElement ) {
	var ArrayConstructor;
	var chunkCount;
	var chunkArray;
	var byteOffset;
	var chunkSize;
	var remainder;
	var buffer;
	var len;
	var t;
	var s;
	var e;
	var n;
	var i;

	len = arr.length;

	// Convert target to integer and handle negative indices:
	if ( isInteger( target ) ) {
		t = target;
	} else {
		t = floor( target );
	}
	if ( t < 0 ) {
		t = max( len + t, 0 );
	} else {
		t = min( t, len );
	}

	// Convert start to integer and handle negative indices:
	if ( start === void 0 ) {
		s = 0;
	} else if ( isInteger( start ) ) {
		s = start;
	} else {
		s = floor( start );
	}
	if ( s < 0 ) {
		s = max( len + s, 0 );
	} else {
		s = min( s, len );
	}

	// Convert end to integer and handle negative indices:
	if ( end === void 0 ) {
		e = len;
	} else if ( isInteger( end ) ) {
		e = end;
	} else {
		e = floor( end );
	}
	if ( e < 0 ) {
		e = max( len + e, 0 );
	} else {
		e = min( e, len );
	}

	// Calculate the number of elements to copy:
	n = min( e - s, len - t );

	if ( n <= 0 ) {
		return arr;
	}

	// Determine the optimal chunk size for copying:
	// For 1-byte elements, use 4-byte chunks
	// For 2-byte elements, use 4-byte chunks (2 elements at a time)
	// For 4-byte elements, use 4-byte chunks (1 element at a time)
	// For 8-byte elements, use 8-byte chunks (1 element at a time)
	if ( bytesPerElement === 1 ) {
		chunkSize = 4; // Copy 4 bytes at a time for 1-byte elements
		ArrayConstructor = Uint32Array;
	} else if ( bytesPerElement === 2 ) {
		chunkSize = 4; // Copy 4 bytes (2 elements) at a time for 2-byte elements
		ArrayConstructor = Uint32Array;
	} else if ( bytesPerElement === 4 ) {
		chunkSize = 4; // Copy 4 bytes (1 element) at a time for 4-byte elements
		ArrayConstructor = Uint32Array;
	} else { // bytesPerElement === 8
		chunkSize = 8; // Copy 8 bytes (1 element) at a time for 8-byte elements
		ArrayConstructor = Float64Array;
	}

	// Check if we can use the optimized path (chunk-aligned and large enough):
	if ( n >= (chunkSize / bytesPerElement) &&
		(s * bytesPerElement) % chunkSize === 0 &&
		(t * bytesPerElement) % chunkSize === 0 ) {
		buffer = arr.buffer;
		byteOffset = arr.byteOffset;

		// Calculate how many chunks we can copy:
		chunkCount = floor((n * bytesPerElement) / chunkSize);
		remainder = n - (chunkCount * (chunkSize / bytesPerElement));

		// Create a view of the same buffer with the appropriate chunk size:
		chunkArray = new ArrayConstructor( buffer, byteOffset, floor((len * bytesPerElement) / chunkSize) ); // eslint-disable-line max-len

		// Copy the chunks:
		if ( t < s ) {
			// Copy from left to right:
			for ( i = 0; i < chunkCount; i++ ) {
				chunkArray[((t * bytesPerElement) / chunkSize) + i] =
					chunkArray[((s * bytesPerElement) / chunkSize) + i];
			}

			// Copy any remaining elements:
			for ( i = 0; i < remainder; i++ ) {
				arr[t + (chunkCount * (chunkSize / bytesPerElement)) + i] =
					arr[s + (chunkCount * (chunkSize / bytesPerElement)) + i];
			}
		} else {
			// Copy from right to left to avoid overwriting elements:
			for ( i = chunkCount - 1; i >= 0; i-- ) {
				chunkArray[((t * bytesPerElement) / chunkSize) + i] =
					chunkArray[((s * bytesPerElement) / chunkSize) + i];
			}

			// Copy any remaining elements:
			for ( i = remainder - 1; i >= 0; i-- ) {
				arr[t + (chunkCount * (chunkSize / bytesPerElement)) + i] =
					arr[s + (chunkCount * (chunkSize / bytesPerElement)) + i];
			}
		}
	} else {
		copyElementByElement( arr, t, s, n );
	}

	return arr;
}

/**
* Copies elements one by one within an array.
*
* @private
* @param {Array|TypedArray} arr - input array
* @param {integer} t - target index
* @param {integer} s - source index
* @param {integer} n - number of elements to copy
* @returns {Array|TypedArray} modified input array
*/
function copyElementByElement( arr, t, s, n ) {
	var i;

	if ( t < s ) {
		// Copy from left to right:
		for ( i = 0; i < n; i++ ) {
			arr[t + i] = arr[s + i];
		}
	} else if ( t > s ) {
		// Copy from right to left to avoid overwriting elements:
		for ( i = n - 1; i >= 0; i-- ) {
			arr[t + i] = arr[s + i];
		}
	}
	return arr;
}

/**
* Copies a sequence of elements within an Int8Array to another location in the same array.
*
* @private
* @param {Int8Array} arr - input array
* @param {integer} target - target index
* @param {integer} [start=0] - source start index
* @param {integer} [end=arr.length] - source end index
* @returns {Int8Array} modified input array
*/
function int8array( arr, target, start, end ) {
	return copyWithinTypedArray( arr, target, start, end, 1 );
}

/**
* Copies a sequence of elements within a Uint8Array to another location in the same array.
*
* @private
* @param {Uint8Array} arr - input array
* @param {integer} target - target index
* @param {integer} [start=0] - source start index
* @param {integer} [end=arr.length] - source end index
* @returns {Uint8Array} modified input array
*/
function uint8array( arr, target, start, end ) {
	return copyWithinTypedArray( arr, target, start, end, 1 );
}

/**
* Copies a sequence of elements within a Uint8ClampedArray to another location in the same array.
*
* @private
* @param {Uint8ClampedArray} arr - input array
* @param {integer} target - target index
* @param {integer} [start=0] - source start index
* @param {integer} [end=arr.length] - source end index
* @returns {Uint8ClampedArray} modified input array
*/
function uint8clampedarray( arr, target, start, end ) {
	return copyWithinTypedArray( arr, target, start, end, 1 );
}

/**
* Copies a sequence of elements within an Int16Array to another location in the same array.
*
* @private
* @param {Int16Array} arr - input array
* @param {integer} target - target index
* @param {integer} [start=0] - source start index
* @param {integer} [end=arr.length] - source end index
* @returns {Int16Array} modified input array
*/
function int16array( arr, target, start, end ) {
	return copyWithinTypedArray( arr, target, start, end, 2 );
}

/**
* Copies a sequence of elements within a Uint16Array to another location in the same array.
*
* @private
* @param {Uint16Array} arr - input array
* @param {integer} target - target index
* @param {integer} [start=0] - source start index
* @param {integer} [end=arr.length] - source end index
* @returns {Uint16Array} modified input array
*/
function uint16array( arr, target, start, end ) {
	return copyWithinTypedArray( arr, target, start, end, 2 );
}

/**
* Copies a sequence of elements within an Int32Array to another location in the same array.
*
* @private
* @param {Int32Array} arr - input array
* @param {integer} target - target index
* @param {integer} [start=0] - source start index
* @param {integer} [end=arr.length] - source end index
* @returns {Int32Array} modified input array
*/
function int32array( arr, target, start, end ) {
	return copyWithinTypedArray( arr, target, start, end, 4 );
}

/**
* Copies a sequence of elements within a Uint32Array to another location in the same array.
*
* @private
* @param {Uint32Array} arr - input array
* @param {integer} target - target index
* @param {integer} [start=0] - source start index
* @param {integer} [end=arr.length] - source end index
* @returns {Uint32Array} modified input array
*/
function uint32array( arr, target, start, end ) {
	return copyWithinTypedArray( arr, target, start, end, 4 );
}

/**
* Copies a sequence of elements within a Float32Array to another location in the same array.
*
* @private
* @param {Float32Array} arr - input array
* @param {integer} target - target index
* @param {integer} [start=0] - source start index
* @param {integer} [end=arr.length] - source end index
* @returns {Float32Array} modified input array
*/
function float32array( arr, target, start, end ) {
	return copyWithinTypedArray( arr, target, start, end, 4 );
}

/**
* Copies a sequence of elements within a Float64Array to another location in the same array.
*
* @private
* @param {Float64Array} arr - input array
* @param {integer} target - target index
* @param {integer} [start=0] - source start index
* @param {integer} [end=arr.length] - source end index
* @returns {Float64Array} modified input array
*/
function float64array( arr, target, start, end ) {
	return copyWithinTypedArray( arr, target, start, end, 8 );
}

/**
* Returns a hash of functions for copying within typed arrays.
*
* @private
* @returns {Object} function hash
*/
function typedarrays() {
	var out = {
		'Int8Array': int8array,
		'Uint8Array': uint8array,
		'Uint8ClampedArray': uint8clampedarray,
		'Int16Array': int16array,
		'Uint16Array': uint16array,
		'Int32Array': int32array,
		'Uint32Array': uint32array,
		'Float32Array': float32array,
		'Float64Array': float64array
	};
	return out;
}

/**
* Copies a sequence of elements within a typed array to another location in the same array.
* Uses optimized implementations based on the array type.
*
* @param {TypedArray} arr - input typed array
* @param {integer} target - target index
* @param {integer} [start=0] - source start index
* @param {integer} [end=arr.length] - source end index
* @returns {TypedArray|null} modified input array or null if not a typed array
*/
function copyWithinTypedArrays( arr, target, start, end ) {
	var typedArrayCopy;
	var type;

	type = typeOf( arr );
	typedArrayCopy = hash[ type ];

	if ( typedArrayCopy ) {
		return typedArrayCopy( arr, target, start, end );
	}
	return null;
}


// MAIN //

hash = typedarrays();


// EXPORTS //

module.exports = copyWithinTypedArrays;
